          const val = char;
          const boxIdx = Math.floor(r / 3) * 3 + Math.floor(c / 3);

          if (rows[r].has(val) || cols[c].has(val) || boxes[boxIdx].has(val)) {
            return false;
          }

          rows[r].add(val);
